1	import { useEffect, useRef, useState } from 'react';
2	import type { RefObject, SyntheticEvent } from 'react';
3	import { defineMessages, useIntl } from 'react-intl';
4	import { useUiCopy } from 'app/hooks/useUiCopy';
5	import { useCartMergeAndCap } from 'app/hooks/useCartMergeAndCap';
6	import { useForm } from 'react-hook-form';
7	import type { UseFormReturn, FieldValues } from 'react-hook-form';
8	import { useDisclosure } from '@chakra-ui/react';
9	import {
10	  AuthHelpers,
11	  useAuthHelper,
12	  useCustomerId,
13	  useCustomerType,
14	  useShopperBasketsV2Mutation as useShopperBasketsMutation,
15	} from '@salesforce/commerce-sdk-react';
16	import { useAuthModal, REGISTER_VIEW } from '@salesforce/retail-react-app/app/hooks/use-auth-modal';
17	import { getConfig } from '@salesforce/pwa-kit-runtime/utils/ssr-config';
18	import {
19	  getAuthorizePasswordlessErrorMessage,
20	  getLoginPasswordlessErrorMessage,
21	  getPasswordlessCallbackUrl,
22	} from '@salesforce/retail-react-app/app/utils/auth-utils';
23	import { API_ERROR_MESSAGE } from '@salesforce/retail-react-app/app/constants';
24	import {
25	  setSessionJSONItem,
26	  getSessionJSONItem,
27	  clearSessionJSONItem,
28	  buildRedirectURI,
29	} from '@salesforce/retail-react-app/app/utils/utils';
30	import useMultiSite from '@salesforce/retail-react-app/app/hooks/use-multi-site';
31	import { useCurrentCustomer } from '@salesforce/retail-react-app/app/hooks/use-current-customer';
32	
33	// Matches the ZimmDrawer slide-in animation duration so focus/modal calls land after the
34	// panel is visible and Chakra's FocusLock has initialised.
35	const DRAWER_ANIMATION_DELAY_MS = 150;
36	
37	// Social IDP sign-in triggers a full-page redirect — onAuthSuccess never fires. Persist an
38	// intent before the redirect so the pending wishlist action can be replayed on return.
39	// Keyed by `intentId` (see UseWishlistAuthDrawerParams) rather than a bare flag: the header
40	// and a PDP can both mount their own `useWishlistAuthDrawer` instance on the same returned
41	// page, each with a different `onAuthSuccess` — a bare boolean let whichever instance's
42	// effect ran first steal the intent and fire its own callback instead of the one that
43	// actually initiated the redirect (SFCC-742 review finding).
44	const PENDING_WISHLIST_INTENT_KEY = 'zimmPendingWishlistAction';
45	
46	type PendingWishlistIntent = { intentId: string; timestamp: number };
47	
48	// A cancelled/abandoned IDP round-trip has no reliable "the user said no" signal we can
49	// observe here — the callback route that owns the actual redirect-back is base SFCC code,
50	// not this hook. Bound the blast radius by age instead: long enough for a slow IDP
51	// round-trip, short enough that an abandoned attempt can't misfire a much later, unrelated
52	// registration in the same tab.
53	const PENDING_WISHLIST_INTENT_MAX_AGE_MS = 5 * 60 * 1000; // 5 minutes
54	
55	// Reads the pending intent, transparently discarding (and clearing) one that's aged out.
56	const readPendingWishlistIntent = (): PendingWishlistIntent | undefined => {
57	  const stored = getSessionJSONItem(PENDING_WISHLIST_INTENT_KEY) as PendingWishlistIntent | undefined;
58	  if (!stored) return undefined;
59	  if (Date.now() - stored.timestamp > PENDING_WISHLIST_INTENT_MAX_AGE_MS) {
60	    clearSessionJSONItem(PENDING_WISHLIST_INTENT_KEY);
61	    return undefined;
62	  }
63	  return stored;
64	};
65	
66	const messages = defineMessages({
67	  drawerTitle: {
68	    id: 'wishlist.auth.drawer.title',
69	    defaultMessage: 'Wishlist',
70	  },
71	});
72	
73	const WISHLIST_DESCRIPTION = 'You must log in or create an account to add items to your wishlist.';
74	
75	type UseWishlistAuthDrawerParams = {
76	  onAuthSuccess?: () => void;
77	  /** Identifies which mounted instance initiated a social-IDP redirect, so that after the
78	   *  round-trip only the matching instance's `onAuthSuccess` fires — see
79	   *  `PENDING_WISHLIST_INTENT_KEY`'s comment. Must be stable and distinct per call site
80	   *  (e.g. `'header-wishlist'`, `'pdp-wishlist'`), not per render. */
81	  intentId: string;
82	};
83	
84	export type UseWishlistAuthDrawerReturn = {
85	  isOpen: boolean;
86	  handleDrawerClose: () => void;
87	  handleTriggerClick: (e: SyntheticEvent<HTMLElement>) => void;
88	  /** Ref pointing at the trigger element; passed to ZimmDrawer's finalFocusRef for AC10 focus-return. */
89	  triggerRef: RefObject<HTMLElement>;
90	  drawerTitle: string;
91	  description: string;
92	  emailValue: string;
93	  onEmailChange: (val: string) => void;
94	  onSendCode: () => Promise<{ success: boolean; error?: string } | void>;
95	  onSignInWithApple?: () => void;
96	  onSignInWithGoogle?: () => void;
97	  isSocialEnabled: boolean;
98	  /** Whether the passwordless email login flow is available per site config. */
99	  isPasswordlessEnabled: boolean;
100	  emailInputRef: RefObject<HTMLInputElement>;
101	  /** Error message from a failed social IDP sign-in attempt; absent when no failure has occurred. */
102	  socialError?: string;
103	  onCreateAccount: () => void;
104	  isOtpAuthOpen: boolean;
105	  onOtpAuthClose: () => void;
106	  form: UseFormReturn<FieldValues>;
107	  handlePasswordlessLogin: (email: string) => Promise<{ success: boolean; error?: string }>;
108	  handleOtpVerification: (pwdlessLoginToken: string) => Promise<{ success: boolean; error?: string }>;
109	  registerModal: ReturnType<typeof useAuthModal>;
110	};
111	
112	/**
113	 * Hook — owns all auth-gate state and SFCC SDK integration for the wishlist auth drawer.
114	 * Extracted from `ZimmWishlistAuthDrawer` so that component stays purely presentational.
115	 * Mirrors the same pattern used by SFCC's own `withRegistration` HOC.
116	 *
117	 * @returns All state and event handlers needed to render and drive the auth gate UI.
118	 */
119	export const useWishlistAuthDrawer = ({
120	  onAuthSuccess,
121	  intentId,
122	}: UseWishlistAuthDrawerParams): UseWishlistAuthDrawerReturn => {
123	  const { formatMessage } = useIntl();
124	  const { t } = useUiCopy();
125	  const { data: customer } = useCurrentCustomer();
126	  const { isRegistered } = useCustomerType();
127	  const customerId = useCustomerId();
128	  const { isOpen, onOpen, onClose } = useDisclosure();
129	  const [isOtpAuthOpen, setIsOtpAuthOpen] = useState(false);
130	  const [emailValue, setEmailValue] = useState('');
131	  const [socialError, setSocialError] = useState<string | undefined>();
132	  // react-hook-form instance needed by SFCC's OtpAuth component for its internal field registration
133	  const form = useForm();
134	  // Points at the email input so Chakra's Drawer focuses it (not the close button) on open.
135	  const emailInputRef = useRef<HTMLInputElement>(null);
136	
137	  // AC10 focus-return: capture the clicked/focused trigger element at click time.
138	  // React.cloneElement ref forwarding only works if the child uses forwardRef — not
139	  // guaranteed for all consumers. document.activeElement at onClick time is always the
140	  // element that was interacted with, regardless of how the child is implemented.
141	  // Typed as HTMLElement (not HTMLElement | null) to satisfy ZimmDrawer's finalFocusRef prop.
142	  const triggerRef = useRef<HTMLElement>(null as unknown as HTMLElement);
143	
144	  const authorizePasswordlessLogin = useAuthHelper(AuthHelpers.AuthorizePasswordless);
145	  const loginPasswordless = useAuthHelper(AuthHelpers.LoginPasswordlessUser);
146	  const authorizeIDP = useAuthHelper(AuthHelpers.AuthorizeIDP);
147	  const mergeBasket = useShopperBasketsMutation('mergeBasket');
148	  // SFCC-250 step 4.2: the shared cap function, called below once the merge above resolves.
149	  // Must be called here, at this hook's own top level — not from inside the effect below — per
150	  // rules of hooks; see `useCartMergeAndCap`'s own doc comment.
151	  const { capBasketQuantities, claimBasketMerge } = useCartMergeAndCap();
152	  // SFCC out-of-the-box registration modal — opened when the user clicks "Create an account"
153	  const registerModal = useAuthModal(REGISTER_VIEW);
154	  const { locale } = useMultiSite();
155	
156	  // eslint-disable-next-line @typescript-eslint/no-explicit-any
157	  const loginConfig = (getConfig().app.login || {}) as any;
158	  const passwordlessConfig = loginConfig.passwordless;
159	  const callbackURL = getPasswordlessCallbackUrl(passwordlessConfig?.callbackURI);
160	  const isSocialEnabled = !!loginConfig.social?.enabled;
161	  const idps: string[] = loginConfig.social?.idps ?? [];
162	  const socialRedirectPath: string = loginConfig.social?.redirectURI ?? '';
163	  const isPasswordlessEnabled = !!passwordlessConfig?.enabled;
164	
165	  // Move focus to the email input once the drawer's enter animation completes.
166	  useEffect(() => {
167	    if (!isOpen) return;
168	    const timer = setTimeout(() => emailInputRef.current?.focus(), DRAWER_ANIMATION_DELAY_MS);
169	    return () => clearTimeout(timer);
170	  }, [isOpen]);
171	
172	  // When the customer transitions to registered while the drawer (or OTP modal) is open,
173	  // close everything, fire the deferred action, and merge the guest basket the shopper was
174	  // just signed out of (passwordless login only — see the merge call's own comment below).
175	  useEffect(() => {
176	    if (isRegistered && (isOpen || isOtpAuthOpen)) {
177	      onClose();
178	      setIsOtpAuthOpen(false);
179	      onAuthSuccess?.();
180	
181	      // Passwordless sign-in switches the SDK session to the registered customer without
182	      // merging the guest basket — left unmerged, the shopper's guest-basket items are
183	      // orphaned, not just miscounted. This mirrors base `use-auth-modal.js`'s own
184	      // `handleMergeBasket`, called from that file's structural equivalent of this effect
185	      // (its own `useEffect(..., [isRegistered])`) rather than from `handleOtpVerification` —
186	      // `isRegistered` (from `useCustomerType()`) is the signal that customer-dependent state
187	      // has actually caught up with the session switch, not just that the login mutation
188	      // resolved, which is presumably why base waits for it here too. The social-IDP route
189	      // needs no merge added here — it redirects through base `social-login-redirect`, which
190	      // already merges on its own. Create-account never reaches this branch — a new customer
191	      // has no prior basket to merge, and `handleTriggerClick` only opens this drawer for a
192	      // guest in the first place, so every path reaching this effect already started as a
193	      // guest session (unlike base, no `prevAuthType === 'guest'` check is needed to establish
194	      // that).
195	      //
196	      // Deliberately does not gate on `hasBasketItem` the way base does: that would add a new
197	      // basket-loading dependency to a hook that has never needed one, and the failure mode of
198	      // getting its timing wrong (a merge silently skipped when it shouldn't be) is worse than
199	      // the cost of one occasional harmless merge call against an empty basket.
200	      //
201	      // productItemMergeMode is 'sum_quantities', not the SDK's 'higher_quantity' default —
202	      // deliberate, not a copy of base's call. This changes the result of every merge, not
203	      // just over-the-cap ones: a guest who adds one unit of an item, then signs into an
204	      // account that already had one unit of that same item, gets two units after merge, not
205	      // one. No AC describes this, so a future reader/tester with no memory of this decision
206	      // needs it stated plainly: two units is intended.
207	      //
208	      // SFCC-250 round 2 — claimBasketMerge decides whether THIS caller gets to issue the real
209	      // network call at all. Base `use-auth-modal.tsx`'s own `handleMergeBasket` reacts to the
210	      // exact same isRegistered transition whenever ITS modal also happens to be open (e.g. a
211	      // guest opens this wishlist drawer, then signs in via the header account icon instead of
212	      // this drawer's own passwordless flow) — without this claim, both called mergeBasket for
213	      // the same sign-in, confirmed live to 409 for whichever lands second and, worse, to
214	      // sometimes make the WINNING caller's own cap correction below silently skip (it saw the
215	      // loser's still-in-flight request and backed off). Guarding on customerId, not a boolean —
216	      // see claimBasketMerge's own JSDoc for why. onClose/onAuthSuccess above still always run
217	      // regardless of which caller wins the claim — those are this drawer's own UI state and the
218	      // deferred wishlist action, unrelated to which caller performs the network write.
219	      if (customerId && claimBasketMerge(customerId)) {
220	        mergeBasket.mutate(
221	          {
222	            headers: {
223	              // Not required since the request has no body, but CommerceAPI throws a
224	              // '419 - Unsupported Media Type' error if this header is removed.
225	              'Content-Type': 'application/json',
226	            },
227	            parameters: {
228	              createDestinationBasket: true,
229	              productItemMergeMode: 'sum_quantities',
230	            },
231	          },
232	          {
233	            // SFCC-250 step 4.2: cap every line at its real max-order-quantity right after a merge
234	            // that may have just combined two same-SKU lines into one now-over-cap line — merge
235	            // must resolve before cap runs, which is exactly what chaining off `onSuccess` (rather
236	            // than a separate, uncoordinated effect) guarantees. A later step (4.4, not yet built)
237	            // will resume any pending wishlist-move action after this settles; `capBasketQuantities`
238	            // already resolves only once its own write (if any) has fully settled, so that future
239	            // addition can sequence after it here without racing it.
240	            //
241	            // Uses `mutate`'s own `onSuccess` rather than switching this call to `mutateAsync` +
242	            // `await`: `mutate` never rejects to its caller (React Query swallows the error into
243	            // the mutation's own state), which is the exact behaviour this merge call already had
244	            // before this step — preserved deliberately, since no AC describes shopper-facing
245	            // feedback for a failed post-login basket merge and inventing copy for it is out of
246	            // this step's scope (interim messaging is `useCartMessages`, step 4.3, not built yet).
247	            // `mutateAsync` + `await` with no `catch` would instead turn that same failure into an
248	            // unhandled promise rejection, which this design avoids entirely rather than papering
249	            // over with an empty `catch`.
250	            onSuccess: (mergedBasket) => {
251	              void capBasketQuantities(mergedBasket);
252	            },
253	          },
254	        );
255	      }
256	    }
257	  }, [isRegistered]);
258	
259	  // Social IDP sign-in redirects the page — the drawer closes and onAuthSuccess never fires.
260	  // On mount, if the shopper is already registered and a pending intent was stored before the
261	  // redirect, consume it immediately and clear the flag so it does not replay on subsequent
262	  // visits — but only when it's THIS instance's own intent (see PENDING_WISHLIST_INTENT_KEY's
263	  // comment): another `useWishlistAuthDrawer` instance mounted on the same returned page (e.g.
264	  // the header, alongside a PDP) leaves a non-matching intent untouched for its rightful owner.
265	  // Follows the same [isRegistered]-only dep pattern as the effect above: onAuthSuccess and
266	  // intentId are intentionally omitted because the intent fires at most once per redirect
267	  // cycle, and the flag is cleared before any re-render that could change either.
268	  useEffect(() => {
269	    if (!isRegistered) return;
270	    const pending = readPendingWishlistIntent();
271	    if (!pending || pending.intentId !== intentId) return;
272	    clearSessionJSONItem(PENDING_WISHLIST_INTENT_KEY);
273	    onAuthSuccess?.();
274	    // eslint-disable-next-line react-hooks/exhaustive-deps
275	  }, [isRegistered]);
276	
277	  const handleDrawerClose = () => {
278	    onClose();
279	    form.reset();
280	    setEmailValue('');
281	  };
282	
283	  const handleTriggerClick = (e: SyntheticEvent<HTMLElement>) => {
284	    // e.currentTarget is always the element the handler is attached to — reliable across
285	    // mouse and keyboard, unlike document.activeElement which may still be body on click.
286	    triggerRef.current = e.currentTarget;
287	    if (customer?.isRegistered) {
288	      onAuthSuccess?.();
289	    } else {
290	      onOpen();
291	    }
292	  };
293	
294	  const handlePasswordlessLogin = async (email: string) => {
295	    try {
296	      const redirectPath = window.location.pathname + (window.location.search ?? '');
297	      await authorizePasswordlessLogin.mutateAsync({
298	        userid: email,
299	        mode: passwordlessConfig?.mode,
300	        locale: locale.id,
301	        ...(callbackURL && {
302	          callbackURI: (() => {
303	            const url = new URL(callbackURL);
304	            url.searchParams.set('redirectUrl', redirectPath);
305	            return url.toString();
306	          })(),
307	        }),
308	      });
309	      return { success: true };
310	    } catch (error) {
311	      return {
312	        success: false,
313	        error: formatMessage(getAuthorizePasswordlessErrorMessage((error as Error).message)),
314	      };
315	    }
316	  };
317	
318	  const handleOtpVerification = async (pwdlessLoginToken: string) => {
319	    try {
320	      await loginPasswordless.mutateAsync({ pwdlessLoginToken });
321	      return { success: true };
322	    } catch (e) {
323	      const errorData = await (e as { response?: { json: () => Promise<{ message: string }> } }).response?.json();
324	      return { success: false, error: formatMessage(getLoginPasswordlessErrorMessage(errorData?.message)) };
325	    }
326	  };
327	
328	  const onSendCode = async () => {
329	    if (!isPasswordlessEnabled) return;
330	    const result = await handlePasswordlessLogin(emailValue);
331	    if (result.success) {
332	      onClose();
333	      // Brief delay lets the drawer finish its exit transition before OTP modal mounts.
334	      setTimeout(() => setIsOtpAuthOpen(true), DRAWER_ANIMATION_DELAY_MS);
335	    }
336	    return result;
337	  };
338	
339	  const onSignInWithApple =
340	    isSocialEnabled && idps.includes('apple')
341	      ? async () => {
342	          setSocialError(undefined);
343	          try {
344	            setSessionJSONItem('returnToPage', window.location.pathname);
345	            // Persist the wishlist intent before the redirect — the page reloads after social
346	            // auth completes and onAuthSuccess would otherwise never fire.
347	            const intent: PendingWishlistIntent = { intentId, timestamp: Date.now() };
348	            setSessionJSONItem(PENDING_WISHLIST_INTENT_KEY, intent);
349	            await authorizeIDP.mutateAsync({
350	              hint: 'apple',
351	              // Social IDP redirects are browser-only — window.location.origin is always available
352	              // here. useAppOrigin() calls useServerContext() which returns undefined in browser,
353	              // causing a destructuring throw; reading the origin directly avoids the SSR hook.
354	              redirectURI: buildRedirectURI(window.location.origin, socialRedirectPath),
355	            });
356	          } catch {
357	            // mutateAsync rejected before the browser navigated away (e.g. a network/config
358	            // error) — no redirect happened, so the intent just stored is already stale.
359	            // Clear it so it can't misfire a later, unrelated registration in this tab.
360	            clearSessionJSONItem(PENDING_WISHLIST_INTENT_KEY);
361	            setSocialError(formatMessage(API_ERROR_MESSAGE));
362	          }
363	        }
364	      : undefined;
365	
366	  const onSignInWithGoogle =
367	    isSocialEnabled && idps.includes('google')
368	      ? async () => {
369	          setSocialError(undefined);
370	          try {
371	            setSessionJSONItem('returnToPage', window.location.pathname);
372	            // Persist the wishlist intent before the redirect — same reason as Apple above.
373	            const intent: PendingWishlistIntent = { intentId, timestamp: Date.now() };
374	            setSessionJSONItem(PENDING_WISHLIST_INTENT_KEY, intent);
375	            await authorizeIDP.mutateAsync({
376	              hint: 'google',
377	              // Social IDP redirects are browser-only — window.location.origin is always available
378	              // here. useAppOrigin() calls useServerContext() which returns undefined in browser,
379	              // causing a destructuring throw; reading the origin directly avoids the SSR hook.
380	              redirectURI: buildRedirectURI(window.location.origin, socialRedirectPath),
381	            });
382	          } catch {
383	            // Same reasoning as Apple's catch above — no redirect occurred, so clear the
384	            // just-stored intent rather than leaving it to misfire later.
385	            clearSessionJSONItem(PENDING_WISHLIST_INTENT_KEY);
386	            setSocialError(formatMessage(API_ERROR_MESSAGE));
387	          }
388	        }
389	      : undefined;
390	
391	  const onCreateAccount = () => {
392	    // Confirmed bug, 2026-09-23 (Marcel's direct report): this used to close the drawer and hand
393	    // off to SFCC's own register modal with no pending intent ever written. `handleDrawerClose()`
394	    // sets `isOpen: false` synchronously, before registration can possibly complete, so the
395	    // isOpen-gated effect above can never fire `onAuthSuccess` for this route — and unlike social
396	    // sign-in, nothing else was writing `PENDING_WISHLIST_INTENT_KEY` either, so the
397	    // isRegistered+matching-intent effect below had nothing to find. Net effect: a guest who
398	    // created a new account instead of using email-code/social login never got their wishlist
399	    // action resumed at all. Persisting the same intent shape social sign-in already uses (see
400	    // onSignInWithApple/onSignInWithGoogle above) fixes it — `isRegistered` flipping true, even
401	    // without a page reload, still re-runs that effect (its dependency is `isRegistered`, not a
402	    // fresh mount), so it now finds this intent and fires `onAuthSuccess` the same way a redirect
403	    // return would. No page reload happens here, so no try/catch cleanup is needed the way the
404	    // social handlers have for a failed redirect — an abandoned/cancelled account creation is
405	    // covered the same way an abandoned social round-trip already is, by the existing 5-minute
406	    // staleness bound on the intent itself.
407	    const intent: PendingWishlistIntent = { intentId, timestamp: Date.now() };
408	    setSessionJSONItem(PENDING_WISHLIST_INTENT_KEY, intent);
409	    handleDrawerClose();
410	    registerModal.onOpen();
411	  };
412	
413	  return {
414	    isOpen,
415	    handleDrawerClose,
416	    handleTriggerClick,
417	    triggerRef,
418	    drawerTitle: formatMessage(messages.drawerTitle),
419	    description: t('login.drawer.wishlist.description', WISHLIST_DESCRIPTION),
420	    emailValue,
421	    onEmailChange: setEmailValue,
422	    onSendCode,
423	    onSignInWithApple,
424	    onSignInWithGoogle,
425	    isSocialEnabled,
426	    isPasswordlessEnabled,
427	    emailInputRef,
428	    socialError,
429	    onCreateAccount,
430	    isOtpAuthOpen,
431	    onOtpAuthClose: () => setIsOtpAuthOpen(false),
432	    form,
433	    handlePasswordlessLogin,
434	    handleOtpVerification,
435	    registerModal,
436	  };
437	};
