  /**
   * Synchronous check-then-claim, called *before* invoking `mergeBasket.mutate(...)` — not after
   * — since the whole point is deciding whether to call it at all. Returns `true` exactly once
   * per customerId (whichever of the (at most two, today) mounted merge-triggering effects reaches
   * it first); every other call for the same customerId returns `false` until a different
   * customerId claims it. See `MERGE_ATTEMPT_QUERY_KEY`'s own comment for why it's keyed this way
   * and what it does not cover.
   */
  claimBasketMerge: (customerId: string) => boolean;
};

/**
 * Hook — the shared "merge coordination + cap" half of SFCC-250's merge-then-cap flow.
 * `capBasketQuantities` has two real callers: the post-auth effect inside
 * `useWishlistAuthDrawer.ts`'s own `isRegistered` effect, and the cart drawer's always-mounted
 * render guard (`overrides/app/pages/cart/cartDrawerContainer.tsx`'s own `useEffect(..., [basket])`).
