// flips true. useWishList()'s own list-lookup query cannot possibly have resolved by then — it
// only starts once customerId is available, which happens in the very same render pass — so
// `wishlist` below is still `undefined` at that exact moment. Every one of the three handlers
// below (`handleAddToWishlist`, `handleAddToWishlistSilent`, `handleRemoveFromWishlist`) used to
// read `wishlist.id` unconditionally, throwing `Cannot read properties of undefined (reading
// 'id')` — for handleAddToWishlistSilent specifically, caught by handleWishlistToggle's own
// try/catch and surfaced as nothing more than a generic "something went wrong" toast, with the
// shopper's actual wishlist-add intent silently lost. Reproduced against a live login (not
// create-account — that path happened not to lose this particular race in testing, but nothing
// in the code structurally prevents it there either; the fix below covers every caller of
// `wishlist`, not just the one path that was reliably reproducible). See useWishlistReady.ts's
// own doc for why this needs a live ref-based read rather than just awaiting `wishlist` again,
// and (round 4) why `customerId` must be passed alongside `wishlist` — without it, the ready
// check can resolve with the *guest's* own wishlist (confirmed live: it already has a real
// `id` by the time this fires), not the now-signed-in customer's.
const { waitForWishlistReady } = useWishlistReady(wishlist, customerId);

// SFCC-11 — the post-sign-in wishlist resume must not run its own write across the
// merge-then-cap window. See waitForCartWritesToSettle's own JSDoc for the confirmed-live
// timings; in short, this add is the one extra mutation the login-only merge path does not
// have, and its presence is what makes the cap skip and leave an over-cap line behind.
const { waitForCartWritesToSettle } = useCartMergeAndCap();

// SFCC-434, AC5/AC6 — passed to the standalone-product ProductView call as a plain array
// rather than a derived boolean: the currently selected size/variant lives inside ProductView
// itself, not here, so only ProductView can compute the variant-scoped result reactively.
const wishlistedProductIds = useMemo(
  () =>
    wishlist?.customerProductListItems
      ?.map((item: { productId?: string }) => item.productId)
      .filter((id: string | undefined): id is string => Boolean(id)) ?? [],
  [wishlist],
);

// SFCC-434 — guards the header wishlist badge against a double-fire mid-mutation.
// isWishlistLoading (above) is the wishlist *query's* loading state, not either mutation's —
// without this, a rapid double-click during the round trip could fire a second create/delete
// before the first resolves.
const isWishlistMutating = createCustomerProductListItem.isPending || deleteCustomerProductListItem.isPending;

const handleAddToWishlist = async (product: SfccProduct, variant: SfccVariant, quantity: number) => {
  const readyWishlist = await waitForWishlistReady();
  if (!readyWishlist?.id) {
    // Genuinely never loaded within the bound above — a real failure, not the ordinary
    // post-sign-in race this fix exists for. Surfaced, not silently dropped.
    showError();
    return;
  }
  const isItemInWishlist = readyWishlist.customerProductListItems?.find(
    (i: { productId?: string }) => i.productId === variant?.productId || i.productId === product?.id,
  );

  if (!isItemInWishlist) {
    createCustomerProductListItem.mutate(
      {
        parameters: {
          listId: readyWishlist.id,
          // SDK param widening — `useCustomerId` returns `string | null`; this branch is
          // only reachable once a wishlist has loaded, which requires a customer.
          customerId: customerId as string,
        },
        body: {
          // NOTE: API does not respect quantity, it always adds 1
          quantity,
          productId: variant?.productId || product?.id,
          public: false,
          priority: 1,
          type: 'product',
        },
      },
      {
        onSuccess: () => {
          toast({
            title: formatMessage(TOAST_MESSAGE_ADDED_TO_WISHLIST, { quantity: 1 }),
            status: 'success',
            action: (
              // it would be better if we could use <Button as={Link}>
              // but unfortunately the Link component is not compatible
              // with Chakra Toast, since the ToastManager is rendered via portal
              // and the toast doesn't have access to intl provider, which is a
