/*
 * SFCC-11 plan step 4.6 — "the real assembly." This is the file `ZimmCartDrawer` (SFCC-315),
 * `cartItemMapper` (SFCC-271/250), `useCartMergeAndCap` (SFCC-250), `useCartMessages` (SFCC-272),
 * `ZimmCartItemActions` (SFCC-272), `ZimmCartEmptyState` (SFCC-272/277) and `ZimmCartButtonGroup`
 * (SFCC-275) were all built anticipating but never wired to — see each of those files' own
 * docblocks, which all point here. Owns `useCurrentBasket()` (and every other commerce-SDK hook
 * this container needs) deliberately: `.claude/rules/components.md`'s container/presentational
 * rule forbids that under `overrides/app/components/`, which is why this lives under
 * `overrides/app/pages/cart/` instead (a sibling file, not `index.tsx` — base `pages/cart/
 * index.jsx` still serves `/cart` untouched, per this plan's own resolved open question 8).
 *
 * 1:1 Figma-alignment audit fix, 2026-09-21: this used to render the mapped `<ProductItem>`
 * array as direct children of `ZimmCartDrawer`, and pass `ZimmCartButtonGroup` via the separate
 * `footer` prop (a full-width strip below everything). Both were wrong against the real Figma
 * structure, confirmed by pulling node 9323:95936 ("Cart Summary") directly: `ZimmCartDrawer`'s
 * own desktop grid (`zimmCartDrawer.css.ts`'s `body` part — `22.5rem`/`26.875rem` tracks, already
 * correct) has exactly two real children in Figma — a single items column (`Cart-item-group`,
 * `gap: 48px` between cards) and a single totals column, whose own first section is the
 * `Cart-button-group` instance (Checkout/Apple Pay/Google Pay, content already matching
 * `ZimmCartButtonGroup` exactly). Rendering the item array as bare siblings let CSS grid's default
 * auto-placement scatter them one-per-column instead of stacking them in column 1; routing the
 * button group through `footer` skipped the grid (and column 2) entirely. Fixed by wrapping the
 * items in their own `Stack` (occupies column 1 as a single grid child) and rendering
 * `ZimmCartButtonGroup` as a second, sibling child (auto-places into column 2) — nothing passed to
 * `footer` any more. The totals breakdown, promotion code, and recommended-for-you sections that
 * share that same Figma column are still out of scope (SFCC-816 and the separately-flagged
 * excluded categories) — only the already-shipped button group's position was corrected here.
 *
 * 1:1 Figma-alignment audit fix, 2026-09-22: `onItemQuantityChange` is now wired to a real
 * `updateItemInBasket` mutation (`updateItemQuantity` below) — the gap this file's own docblock
 * used to flag here as deliberately out of scope. Confirmed live: the stepper's own local,
 * optimistic state (`ProductItem`'s `handleStepperQuantityChange`) already updated the on-screen
 * number correctly; what was missing was persistence — closing and reopening the drawer remounts
 * every `ProductItem` fresh from the real, untouched basket, so a change that never reached SFCC
 * silently reverted. Same `mutateAsync`-then-boolean-result shape as `removeItem` below, so a
 * rejected mutation resolves `false` and `ProductItem` correctly declines to commit locally.
 *
 * Deliberately out of scope (disclosed, not silently dropped):
 * - Per-line "isRemoving" loading-spinner feedback (base `pages/cart/index.jsx`'s own
 *   `removingItemIds` state) is not reproduced — no pass criterion asks for it, and `ProductItem`
 *   already has its own `showLoading` prop for exactly this if a future step wants it.
 */

type SfccBasket = ShopperBasketsV2Types.Basket;
type SfccBasketProductItem = ShopperBasketsV2Types.BasketProductItem;

// `useCurrentBasket` is a base, untyped (`.js`) hook — AGENTS.md's "Commerce SDK types not
// importable" gotcha, same pattern cartItemMapper.ts/useCartMergeAndCap.ts already use for the
// identical gap. `ShopperBasketsV2Types.Basket` (not the V1 `ShopperBasketsTypes.Basket`
// cartItemMapper.ts's own `CartLineItem` type references) is used here to match
// useCartMergeAndCap's own `CartCapBasket` — the two SDK namespaces' generated `Basket`/
// `ProductItem`/`BasketProductItem` shapes are field-for-field identical (verified directly
// against commerce-sdk-isomorphic's own generated .d.ts, both fully-optional plus the same
// `{[key: string]: any}` catch-all), so a value typed against one satisfies the other
// structurally — no second, parallel type is needed for the cartItemMapper.selectCartItemProps
// call below.
type UseCurrentBasketReturn = {
  data: SfccBasket | undefined;
  isLoading: boolean;
  // 1:1 Figma-alignment audit fix, 2026-09-22 (Marcel's direct request) — `useCurrentBasket`
  // spreads every other react-query field through as `...restOfQuery` (see its own source),
  // `refetch` included; just not previously named here since nothing needed it. Same query the
  // header's own bag-count badge reads via its own separate `useCurrentBasket()` call — calling
  // it here forces that badge to reflect a real mutation immediately rather than relying on the
  // SDK's own automatic cache-splice (updateItemInBasket/removeItemFromBasket's cache-update-
  // matrix entries), which traced out as correct on paper but wasn't visibly keeping the header in
  // sync in practice.
  refetch: () => Promise<unknown>;
};

const CART_WISHLIST_INTENT_ID = 'cart-wishlist';

// The API does not respect this value — it always adds 1 regardless of what is sent (confirmed,
// overrides/app/pages/product-detail/index.tsx's own identical comment against the same
// createCustomerProductListItem call). Sent explicitly anyway, as a named constant rather than an
// inline `1`, per conventions.md's "no magic numbers" rule.
const WISHLIST_ADD_QUANTITY = 1;

// Sub-pixel layout rounding can leave a fraction of a px of "scroll left" in scrollHeight -
// scrollTop - clientHeight even when the items column is visually fully scrolled — see
// CartItemsColumn's own effect for where this is used.
const SCROLL_BOTTOM_EPSILON_PX = 1;

// Confirmed bug, 2026-09-23 (Marcel's direct report, live-tested): create-account (unlike
// email-code/social login, which stay on or return to the same page) navigates to /account as
// part of the same success event — useCartDrawer.ts's own [pathname]-keyed effect closes the
// cart on every route change, and calling onOpen() synchronously from handleAuthSuccess below
// raced that same-tick navigation, losing the reopen. Matches
// useWishlistAuthDrawer.ts's own DRAWER_ANIMATION_DELAY_MS — the same settle-before-the-next-
// transition shape, applied here to a route transition instead of a drawer animation.
const REOPEN_AFTER_ACCOUNT_CREATION_DELAY_MS = 150;

export type CartDrawerContainerProps = {
  /** Whether the drawer is open. Owned by whichever component mounts this container (the
   *  drawer-open lifecycle, per step 9's own `useCartDrawer()` provider) — this container never
   *  reads or owns that state itself (pass criterion 7). */
  isOpen: boolean;
  /** Called on backdrop click, Escape, and the close button — forwarded to `ZimmCartDrawer`
   *  verbatim, not wrapped. */
  onClose: () => void;
  /**
   * 1:1 Figma-alignment audit fix, 2026-09-22 (Marcel's own direct decision): re-opens this same
   * drawer once a guest's wishlist auth flow succeeds (see `handleAuthSuccess` below) — the cart
   * now closes itself before that flow starts (see `openGuestWishlistDrawer`), rather than the
   * two drawers stacking. Sourced from `useCartDrawer()`'s own Context value in `useCartDrawer.ts`
   * — passed down as a prop here, not called directly in this file, specifically to avoid a
   * circular import: `useCartDrawer.ts` already imports `CartDrawerContainer` itself (to render it
   * inside `CartDrawerProvider`), so this file importing back from `useCartDrawer.ts` would create
   * a cycle. The hook's own exported signature (what every other consumer — header, drawer-menu,
   * product-view — receives from `useCartDrawer()`) is unchanged; only `CartDrawerProvider`'s own
   * internal wiring to this specific, already-tightly-coupled child gained one more prop.
   */
  onOpen: (trigger?: HTMLElement | null) => void;
  /** Forwarded to `ZimmCartDrawer`'s own `finalFocusRef` (AC10 focus-return for the cart drawer
   *  itself) — see this container's own `openGuestWishlistDrawer` for the separate, disclosed
   *  focus-return story for the nested wishlist auth drawer. */
  finalFocusRef?: React.RefObject<HTMLElement>;
};

/**
 * Column 1 (items) — split out of the main component body for one specific reason, not just
 * components.md's ~150-line guideline (see `CartWishlistAuthGate` below for that ordinary case):
 * `useIsFooterRevealed()` (zimmCartDrawer's own `ScrollAreaContext`) only resolves correctly for
 * a component actually rendered *underneath* `ZimmCartDrawer`'s Provider in the real React tree.
 * `CartDrawerContainer` is the component that *renders* `<ZimmCartDrawer>` — calling the hook in
 * its own body would read the context's default (`false`), always, regardless of real scroll
 * state, because `CartDrawerContainer` sits *above* the Provider, not below it, even though this
 * component's own JSX is textually written inside `CartDrawerContainer` and passed through as
 * `children`. A real, separate component is the only way to actually be a descendant.
 *
 * 1:1 Figma-alignment audit fix, 2026-09-22 (Marcel's direct report): scrolling up must fully
 * re-hide the footer (Zimmermann-benefits) before this column's own independent scroll responds
 * again — native nested-scroll bubbling alone can't guarantee that (which element a wheel/
 * trackpad gesture actually scrolls depends on cursor position, not on a "which phase are we
 * in" rule). Setting `overflowY: 'hidden'` for the entire time the footer is even partially
 * revealed makes this column completely unresponsive to scroll input during that phase — so
 * every gesture, regardless of where the cursor is, reaches `scrollArea` (zimmCartDrawer/
 * index.tsx) instead, which is the only thing that can un-reveal the footer. Once it's back at
 * `scrollTop: 0`, this column becomes scrollable again, picking up exactly where its own
 * `scrollTop` already was — hidden overflow doesn't reset it.
 *
 * Round 2 (Marcel's direct correction, same day): the above only ever covered scroll gestures
 * that land on THIS column. A gesture over the totals column, or the gutter between the two,
 * has nothing of its own to scroll and bubbles straight to `scrollArea` regardless of whether
 * this column has reached its own bottom yet — so the footer could reveal early simply because
 * the cursor wasn't over the items column when the user scrolled. Fixed from the other side:
 * this column now reports its own "at bottom" state up to `ZimmCartDrawer` via
 * `useReportLhsAtBottom()`, which gates `scrollArea`'s own `overflowY` — see that hook's own doc
 * comment. Revealing the footer is now unreachable from ANY cursor position until this column's
 * own scroll genuinely has nowhere further to go, not just unreachable via this column itself.
 */
const CartItemsColumn = ({
  productItems,
  productsById,
  isProductsLoading,
  isGuestState,
  alreadyInWishlistItemIds,
  onAlreadyInWishlist,
  onClose,
  updateItemQuantity,
  removeItem,
  moveToWishlist,
  openGuestWishlistDrawer,
}: {
  productItems: SfccBasketProductItem[];
  productsById: Record<string, ShopperProductsTypes.Product>;
  isProductsLoading: boolean;
  isGuestState: boolean;
  /** Which lines just got an 'already-in-wishlist' result from ZimmCartItemActions' own
   *  attemptMoveToWishlist — that result is otherwise invisible to this container (see
   *  ZimmCartItemActions' own onAlreadyInWishlist doc for why), and it's this container, not
   *  that molecule, that owns ProductItem's `message` slot. Owned by CartDrawerContainer, not
   *  this component — see that container's own doc comment on why (Chakra's Drawer stops
   *  re-rendering closed children, so a reset-on-close effect has to live somewhere that keeps
   *  running regardless). */
  alreadyInWishlistItemIds: Set<string>;
  onAlreadyInWishlist: (itemId: string) => void;
  onClose: () => void;
  updateItemQuantity: (itemId: string | undefined, quantity: number) => Promise<boolean>;
  removeItem: (itemId?: string) => Promise<void>;
  moveToWishlist: (productId: string) => Promise<WishlistMoveResult>;
  openGuestWishlistDrawer: () => void;
}) => {
  const isFooterRevealed = useIsFooterRevealed();
  const reportLhsAtBottom = useReportLhsAtBottom();
  const { t } = useUiCopy();

  // Callback ref, not useRef + empty-deps useEffect — same reasoning as zimmCartDrawer/index.tsx's
  // own scrollAreaRefCallback: this Stack can mount/remount (e.g. the empty-state branch swaps
  // it out of the tree entirely) independently of this component's own lifecycle.
  const [itemsColumnEl, setItemsColumnEl] = useState<HTMLDivElement | null>(null);
  const itemsColumnRefCallback = useCallback((node: HTMLDivElement | null) => setItemsColumnEl(node), []);

  useEffect(() => {
    if (!itemsColumnEl) return;
    // <= 1, not === 0: sub-pixel layout rounding can leave a fraction of a px of "scroll left"
    // even when the column is visually fully scrolled. Reported once immediately (not only on
    // the first scroll event) so a short cart — nothing to scroll internally at all, scrollHeight
    // <= clientHeight — still unlocks scrollArea from the very first render, per this column's
    // own docblock (round 2).
    const reportAtBottom = () => {
      const remaining = itemsColumnEl.scrollHeight - itemsColumnEl.scrollTop - itemsColumnEl.clientHeight;
      reportLhsAtBottom(remaining <= SCROLL_BOTTOM_EPSILON_PX);
    };
    reportAtBottom();
    itemsColumnEl.addEventListener('scroll', reportAtBottom);
    return () => itemsColumnEl.removeEventListener('scroll', reportAtBottom);
  }, [itemsColumnEl, reportLhsAtBottom]);

  return (
    // Column 1 (22.5rem desktop track) — see this file's own 2026-09-21 docblock note. 48px
    // (var(--zimm-scale-1200)) confirmed against the real "Cart-item-group" node's own gap at
    // the desktop/xlarge frame; not independently re-confirmed at a separate mobile frame, so
    // this is applied at both breakpoints rather than guessed at for mobile specifically.
    <Stack
      ref={itemsColumnRefCallback}
      // data-testid: a generic layout container with no semantic role of its own — see
      // .claude/rules/testing.md's Page Object Model selector priority, "complex layout blocks"
      // — used by this file's own suite to simulate real scroll metrics (same reasoning as
      // zimmCartDrawer/index.tsx's own "cart-scroll-area" testid).
      data-testid="cart-items-column"
      spacing="var(--zimm-scale-1200)"
      sx={{
        [`@media (min-width: ${breakpoints.xl})`]: {
          // 1:1 Figma-alignment audit fix, 2026-09-22 (Marcel's direct report) — desktop-only.
          // Scoped to `xl`+ only — below that, `body` collapses to a single flex column (no
          // sibling totals column to stay static next to), so this Stack scrolls as part of the
          // whole drawer as before, unaffected by isFooterRevealed. See this component's own
          // docblock for why the value toggles between 'hidden'/'auto' at all.
          overflowY: isFooterRevealed ? 'hidden' : 'auto',
          minHeight: 0,
          // Fully hidden, no visible cue (Marcel's direct call, 2026-09-22) — scrolling itself
          // is unaffected by either property; both only suppress the scrollbar's own rendering,
          // so wheel/trackpad/touch/keyboard scrolling all still work.
          scrollbarWidth: 'none', // Firefox
          '&::-webkit-scrollbar': { display: 'none' }, // Chromium/Safari
          // 1:1 Figma-alignment audit fix, 2026-09-22 (Marcel's direct report) — breathing room
          // below the last item once scrolled to the end. Inferred, not independently verified
          // in Figma: the static file has no "scrolled to the end" state for a dynamic list to
          // carry its own value. Matches the totals column's own real, Figma-confirmed 32px
          // bottom padding below (its own `Totals-summary` node: `pb-[var(--alias/space/800,
          // 32px)]`) for consistency between the two columns, using the same
          // var(--zimm-scale-2xl) = 32px token this file already keys off elsewhere.
          paddingBottom: 'var(--zimm-scale-2xl)',
        },
      }}
    >
      {/* Most-recently-added item first (Marcel's direct request, 2026-09-24) — the basket API
          returns `productItems` in insertion order (oldest first); `[...productItems]` copies
          before `.reverse()` (which mutates in place) so this component never writes to the
          `productItems` prop it was handed. `itemCount`/`productIds` upstream stay keyed off the
          original, un-reversed array — both are order-independent (a sum and an id lookup), so
          only this render needs the flipped copy. */}
      {[...productItems].reverse().map((item) => {
        const fullProduct = item.productId ? productsById?.[item.productId] : undefined;
        const mergedProduct = {
          ...item,
          ...fullProduct,
          // Re-asserted after both spreads, matching base's own precedent exactly: the fetched
          // catalog Product record can carry its own `price` field, which would otherwise
          // silently overwrite the basket-line's real, discount-aware price.
          price: item.price,
          quantity: item.quantity,
          isProductUnavailable: !isProductsLoading ? !fullProduct : undefined,
        };
        // Pass criterion 1 — cartItemMapper's output used verbatim: productId/name feed
        // ZimmCartItemActions below (as productId/productName) — not a second, hand-rolled
        // mapping. The full mergedProduct object, not this mapped result, is what ProductItem
        // itself needs (see this file's own module docblock and cartItemMapper.ts's own
        // docblock for why its output alone is not a complete `product` prop).
        const mapped = selectCartItemProps(mergedProduct);

        // SFCC-11 1:1 Figma-alignment audit fix, 2026-09-22: the two item-level inline messages
        // this container can actually populate today (the rest — OOS/Unavailable — depend on
        // SFCC-282/796, not built). Copy sourced from Contentful's uiCopy (never hardcoded), per
        // Marcel's own direct goal. Max-quantity is a pure derived value — the same
        // getMaxOrderQuantity call ProductItem's own stepper already uses for its `max` — so it
        // needs no state and self-corrects the moment quantity changes. Already-in-wishlist is
        // event-driven (see the state above) and deliberately checked second: if a line is
        // somehow both at max quantity and just failed a wishlist move, max-quantity wins — a
        // disclosed default (Marcel's own review point), not a Figma-sourced rule, since no
        // single node shows both at once.
        // mergedProduct's inferred shape has `id: string | undefined` (the basket ProductItem
        // half may lack one pre-merge) — getMaxOrderQuantity's param type requires `id: string`
        // per the full Product type it extends, but only ever reads `c_maxOrderQuantity`, never
        // `id`. product-item/index.tsx's own identical call sidesteps this the same way, just
        // one layer up (its `product` prop is typed `SfccProduct = any`) — asserted narrowly
        // here instead, since mergedProduct keeps its real inferred type everywhere else in this
        // file (selectCartItemProps, ProductItem's own `product` prop).
        const isAtMaxQuantity =
          (item.quantity ?? 0) >= getMaxOrderQuantity(mergedProduct as Parameters<typeof getMaxOrderQuantity>[0]);
        const isAlreadyInWishlist = Boolean(item.itemId) && alreadyInWishlistItemIds.has(item.itemId as string);
        const message = isAtMaxQuantity
          ? {
              variant: 'warning' as const,
              text: t('cart.item.maxQuantityReached', 'Maximum purchase quantity reached for this size'),
            }
          : isAlreadyInWishlist
          ? {
              variant: 'warning' as const,
              text: t('cart.item.alreadyInWishlist', 'Item already exists in Wishlist'),
            }
          : undefined;

        return (
          <ProductItem
            key={item.itemId}
            product={mergedProduct}
            // 2026-09-21 (Marcel's direct request): closes the drawer when this item's own
            // image/name link is clicked, covering the one case the drawer's general
            // [pathname]-close effect can't — a shopper already on this exact product's PDP,
            // clicking its own cart-item link, which is a same-pathname no-op that effect
            // never sees. Navigating to a DIFFERENT product's PDP is already covered by that
            // effect for free; this prop is what makes the same-PDP case behave the same way
            // instead of leaving the drawer stuck open over the page the shopper just clicked
            // to see. See product-item/index.tsx's own doc.
            onCartItemNavigate={onClose}
            onItemQuantityChange={(quantity) => updateItemQuantity(item.itemId, quantity)}
            message={message}
            secondaryActions={
              <ZimmCartItemActions
                productId={mapped.productId ?? ''}
                productName={mapped.name}
                isGuest={isGuestState}
                onRemove={() => removeItem(item.itemId)}
                onMoveToWishlist={() => moveToWishlist(mapped.productId ?? '')}
                onGuestWishlistClick={openGuestWishlistDrawer}
                onAlreadyInWishlist={item.itemId ? () => onAlreadyInWishlist(item.itemId as string) : undefined}
              />
            }
          />
        );
      })}
    </Stack>
  );
};

/**
 * Presentational sub-tree for the one shared wishlist auth gate — split out of the main component
 * body purely for readability (components.md's ~150-line guideline); still the same one file, no
 * new component/props contract for anything outside this module to depend on. Mirrors
 * `ZimmWishlistAuthDrawer`'s own render body (`app/components/ui-kits/organisms/
 * zimmWishlistAuthDrawer/index.tsx`) minus the single-trigger `cloneElement` wrapping, which does
 * not apply here — see this file's own `openGuestWishlistDrawer` for why a many-rows container
 * cannot use that component as-is. Duplicating this specific composition (rather than extracting
 * a shared piece out of `zimmWishlistAuthDrawer/index.tsx`) is a disclosed, deliberate tradeoff:
 * that file is outside this step's manifest, and its `children: React.ReactElement` contract is
 * structurally single-trigger, so there is no lower-risk shared extraction point available from
 * this step's own scope.
 */
const CartWishlistAuthGate = ({ wishlistAuthDrawer }: { wishlistAuthDrawer: UseWishlistAuthDrawerReturn }) => {
  // SFCC-926 (Figma), mirrored from zimmWishlistAuthDrawer/index.tsx: mobile full-width (`large`,
  // which is itself responsive down to mobile — see zimmDrawer.css.ts), desktop (>= xl) `small`.
  // That file also tracks an `isTabletOrAbove` value that is computed but never actually read by
  // its own final `drawerSize` ternary (checked directly against its current code, not assumed) —
  // not reproduced here since duplicating unused state would just be a second copy of the same
  // gap, not a faithful port of real behaviour.
  const [isDesktopOrAbove, setIsDesktopOrAbove] = useState(false);
  useEffect(() => {
    const desktopMq = window.matchMedia(`(min-width: ${breakpoints.xl})`);
    setIsDesktopOrAbove(desktopMq.matches);
    const onDesktop = (e: MediaQueryListEvent) => setIsDesktopOrAbove(e.matches);
    desktopMq.addEventListener('change', onDesktop);
    return () => desktopMq.removeEventListener('change', onDesktop);
  }, []);
  const drawerSize: ZimmDrawerSize = isDesktopOrAbove ? 'small' : 'large';

  return (
    <>
      <ZimmDrawer
        isOpen={wishlistAuthDrawer.isOpen}
        onClose={wishlistAuthDrawer.handleDrawerClose}
        size={drawerSize}
        title={wishlistAuthDrawer.drawerTitle}
        finalFocusRef={wishlistAuthDrawer.triggerRef}
        initialFocusRef={wishlistAuthDrawer.emailInputRef}
      >
        <ErrorFallback>
          <ZimmAuthDrawerContent
            description={wishlistAuthDrawer.description}
            emailValue={wishlistAuthDrawer.emailValue}
            onEmailChange={wishlistAuthDrawer.onEmailChange}
            onSendCode={wishlistAuthDrawer.onSendCode}
            onSignInWithApple={wishlistAuthDrawer.onSignInWithApple}
            onSignInWithGoogle={wishlistAuthDrawer.onSignInWithGoogle}
            onCreateAccount={wishlistAuthDrawer.onCreateAccount}
            socialEnabled={wishlistAuthDrawer.isSocialEnabled}
            passwordlessEnabled={wishlistAuthDrawer.isPasswordlessEnabled}
            initialFocusRef={wishlistAuthDrawer.emailInputRef}
          />
        </ErrorFallback>
      </ZimmDrawer>
      <AuthModal {...wishlistAuthDrawer.registerModal} />
      <OtpAuth
        isOpen={wishlistAuthDrawer.isOtpAuthOpen}
        onClose={wishlistAuthDrawer.onOtpAuthClose}
        form={wishlistAuthDrawer.form}
        handleSendEmailOtp={wishlistAuthDrawer.handlePasswordlessLogin}
        handleOtpVerification={wishlistAuthDrawer.handleOtpVerification}
        hideCheckoutAsGuestButton={true}
      />
    </>
  );
};

/**
 * Container — the real cart-drawer content assembly (SFCC-11 plan step 4.6). See this file's own
 * module docblock for why this owns `useCurrentBasket()` and lives under `pages/cart/`, not
 * `components/`.
 */
export const CartDrawerContainer = ({ isOpen, onClose, onOpen, finalFocusRef }: CartDrawerContainerProps) => {
  const { data: basket, refetch: refetchBasket } = useCurrentBasket() as unknown as UseCurrentBasketReturn;
  const productItems: SfccBasketProductItem[] = basket?.productItems ?? [];
  // 1:1 Figma-alignment audit fix, 2026-09-22 (Marcel's direct call): total quantity across every
  // line, not `productItems.length` (distinct line count) — the value this used to be. Neither
  // Figma (the drawer header node renders a literal "BAG • #" placeholder, no dev annotation) nor
  // ZimmCartDrawer's own doc comment (an unsourced assumption from whenever it was first built)
  // settle which metric is correct, and Marcel's Jira token wasn't available to check the
  // originating ticket's AC either — so this is sourced from the current production
  // www.zimmermann.com site's own header behaviour instead, confirmed by Marcel directly: it
  // shows total quantity, not distinct products. `=== 0` below is unaffected either way — a truly
  // empty basket has both metrics at zero.
  const itemCount = productItems.reduce((total, item) => total + (item.quantity ?? 0), 0);

  // SFCC-11 1:1 Figma-alignment audit fix, 2026-09-22: lives here, not inside CartItemsColumn —
  // confirmed live (not assumed) that Chakra's Drawer/Modal stops re-rendering its children once
  // `isOpen` goes false, rather than rendering them once more with the new value before removal,
  // so a reset effect inside CartItemsColumn watching its own `isOpen` prop never actually runs.
  // This component is never unmounted by its own `isOpen` toggling (it's the thing that HANDS
  // `isOpen` to ZimmCartDrawer, not something ZimmCartDrawer's own open/closed state controls),
  // so its effects keep running regardless of whether the drawer is visually open. See
  // CartItemsColumn's own doc for what this state is and why (Marcel's own direct call: clears on
  // close, not a timer, not the next interaction with the line).
  const [alreadyInWishlistItemIds, setAlreadyInWishlistItemIds] = useState<Set<string>>(new Set());
  useEffect(() => {
    if (!isOpen) setAlreadyInWishlistItemIds(new Set());
  }, [isOpen]);
  const markAlreadyInWishlist = useCallback((itemId: string) => {
    setAlreadyInWishlistItemIds((prev) => {
      const next = new Set(prev);
      next.add(itemId);
      return next;
    });
  }, []);

  // Base `pages/cart/index.jsx`'s own real precedent for building ProductItem's `product` prop
  // (`{...productItem, ...productsByItemId[productItem.itemId], price: productItem.price,
  // quantity: ...}`, node_modules/@salesforce/retail-react-app/app/pages/cart/index.jsx) — minus
  // `allImages: true` on the fetch (over-fetching, and the exact parameter implicated in the
  // SFCC-29 outage) and minus its bundle/bonus-product/multi-location-inventory enrichment (real
  // complexity this epic never asked for). One correction against that same base file, found by
  // reading it in full rather than trusting a paraphrase: its OWN per-line lookup map
  // (`productsByItemId`, a second, separate useMemo) is keyed by `productItem.itemId`, but is
  // itself built from `products?.[productItem?.productId]` — i.e. the raw `useProducts` fetch
  // below is keyed by PRODUCT id, not item id, and the re-keying-by-itemId step exists there only
  // to support the bundle-child-inventory enrichment this container does not replicate. This
  // container looks the fetched product up by `productId` directly, with no intermediate re-keyed
  // map.
  // The generated `getProducts` query parameters type this SDK call resolves against
  // (`getProductsQueryParameters`, commerce-sdk-isomorphic) types `ids` as `Array<string>` — base
  // `pages/cart/index.jsx`'s own equivalent call passes a comma-joined string instead (its own
  // file is untyped `.jsx`, so nothing catches the mismatch there); an array is what this
  // TypeScript call site actually needs.
  const productIds = productItems.map((item) => item.productId).filter((id): id is string => Boolean(id));
  const { data: productsResult, isLoading: isProductsLoading } = useProducts(
    { parameters: { ids: productIds, perPricebook: true } },
    { enabled: productIds.length > 0 },
  );
  // Reshaped outside the hook call, not via a `select` option: commerce-sdk-react's own
  // `ApiQueryOptions` type pins `select`'s return type to the query's own raw result type
  // (`UseQueryOptions<DataType<Method>, unknown, DataType<Method>, ...>` — the third, `TData`,
  // generic is hard-coded to match the first), so a `select` reshaping into a keyed map does not
  // type-check here even though base's own untyped `.jsx` equivalent does exactly this via its
  // own `select`. A `useMemo` outside the hook achieves the identical keyed-by-product-id shape.
  const productsById = useMemo(
    () =>
      (productsResult?.data ?? []).reduce((acc: Record<string, ShopperProductsTypes.Product>, product) => {
        acc[product.id] = product;
        return acc;
      }, {} as Record<string, ShopperProductsTypes.Product>),
    [productsResult],
  );

  /* -------------------------------------------------------------------------------------------
   * Pass criterion 2 — useCartMergeAndCap's render guard, this hook's second of two call sites
   * (the first, the post-auth callback, was wired into useWishlistAuthDrawer.ts back in step 4.2).
   * Keyed on `[basket]` (react-query returns a stable reference across renders where the basket
   * data hasn't actually changed, thanks to structural sharing) rather than on
   * `capBasketQuantities` itself, which useCartMergeAndCap does not memoise — a fresh function
   * reference every render, so including it here would re-run this effect on every render instead
   * of only on a real basket-state change. capBasketQuantities' own internal guards (mutation-in-
   * flight, already-attempted-this-version) would make an extra call harmless regardless, but
   * "runs on a basket-driven re-render" is this criterion's own explicit framing.
   * ---------------------------------------------------------------------------------------- */
  const { capBasketQuantities } = useCartMergeAndCap();
  const { notifyMaxQuantityReached } = useCartMessages();
  // notifyAddedToWishlist/notifyAlreadyInWishlist are NOT called from this container — verified
  // directly against zimmCartItemActions/index.tsx's own current code (not assumed from this
  // step's own plan text, which describes all three as called "by this container"): ZimmCartItemActions
  // already calls useCartMessages itself and fires both from its own attemptMoveToWishlist. Calling
  // them again here would double-fire the toast for a single successful move. notifyMaxQuantityReached
  // is the one function with no other call site anywhere in this codebase — genuinely this
  // container's own responsibility, fired below once the render guard reports a real correction.
  useEffect(() => {
    if (!basket?.basketId) return;
    void capBasketQuantities(basket).then((result) => {
      if (result.status === 'corrected') {
        notifyMaxQuantityReached();
      }
    });
  }, [basket]);

  /* -------------------------------------------------------------------------------------------
   * Pass criterion 4 — the wishlist-move resume must wait for the merge-then-cap chain to settle.
   * See useWishlistAuthDrawer.ts's own isRegistered effect: onAuthSuccess fires synchronously,
   * immediately before mergeBasket.mutate(...) — so isGuest cannot simply mirror `!isRegistered`
   * one-for-one, or ZimmCartItemActions' resumed usePendingWishlistItem effect (keyed on
   * `[isGuest]`) could fire before the merge has even started.
   *
   * hasPendingPostAuthSettleRef is a ref, not React state, deliberately: useWishlistAuthDrawer()
   * is called (below) before this gating effect is declared, so within the SAME commit, its own
   * internal [isRegistered] effect runs first and calls handleAuthSuccess synchronously — a
   * setState there would only become visible on a LATER render (one render behind), which would
   * let this effect's very first run (in the same commit as the isRegistered flip) read a stale
   * "not yet settling" value and flip isGuestState to false immediately, before mergeBasket.mutate
   * has registered anything in the mutation cache. A ref mutation is visible immediately to any
   * code running later in the same synchronous effect-flush pass, which is exactly what this
   * needs. This is the same class of stale-closure trap useCartMergeAndCap.ts's own docblock
   * already documents fixing (a React-render-time value instead of a live read) — applied here to
   * the ordering between two different hooks in the same fiber rather than to a single async
   * closure.
   *
   * queryClient.isMutating() (a live, imperative read, taken fresh at the moment this effect body
   * runs) — not the reactive `isMutatingSignal` value below — is what actually decides whether to
   * flip isGuestState. `isMutatingSignal` (useIsMutating()) exists purely so this effect re-runs
   * every time the app-wide mutation count changes, giving it a fresh chance to re-check the live
   * value; using its own render-time value directly would reintroduce the identical stale-read
   * risk described above. Matches useCartMergeAndCap.ts's own documented reasoning for the same
   * hook pairing (queryClient.isMutating() for correctness, useIsMutating() for reactivity).
   * ---------------------------------------------------------------------------------------- */
  const { isRegistered } = useCustomerType();
  const [isGuestState, setIsGuestState] = useState(!isRegistered);
  const queryClient = useQueryClient();
  const isMutatingSignal = useIsMutating();
  const hasPendingPostAuthSettleRef = useRef(false);

  // 1:1 Figma-alignment audit fix, 2026-09-22 (Marcel's own direct decision): re-opens the cart
  // once a guest's wishlist auth flow succeeds — the counterpart to openGuestWishlistDrawer
  // below closing it first. useWishlistAuthDrawer's own sessionStorage fallback (its own
  // PENDING_WISHLIST_INTENT_KEY) already guarantees onAuthSuccess fires here reliably whether
  // the shopper authenticated in-page (email code) or via a full-page social-IDP redirect — this
  // callback doesn't need to distinguish the two paths itself. No trigger element is passed to
  // onOpen: there's no real user click to capture at this exact moment (this fires from an auth
  // callback, not a click handler), so the previous trigger — whatever originally opened the
  // cart — is left in place as the AC10 focus-return target once the cart finally closes for
  // good, per onOpen's own doc ("the previous trigger... is left untouched rather than cleared").
  // Once the cart remounts, ZimmCartItemActions/usePendingWishlistItem's own existing mount-time
  // sessionStorage check (already built for the redirect case) naturally resumes the pending
  // move — nothing new needed there.
  //
  // Confirmed bug, 2026-09-23 (Marcel's direct report, live-tested): create-account's own
  // onAuthSuccess fires as part of the very same event that navigates to /account (see
  // REOPEN_AFTER_ACCOUNT_CREATION_DELAY_MS's own doc comment for why) — calling onOpen()
  // synchronously here raced that navigation and lost, every time, live-confirmed (the drawer
  // stayed closed on /account, though the resumed move itself still completed correctly once
  // manually reopened — proving this race, not the resume logic, was the actual gap). Deferred
  // by the same short delay this codebase already uses for an analogous settle-then-transition
  // case, so the navigation's own pathname-triggered close (useCartDrawer.ts) has already
  // resolved before this reopen runs, rather than the two racing in the same tick. Harmless for
  // the email-code/social-login paths too: neither navigates away, so this delay just means a
  // barely perceptible pause before a reopen that was always going to happen regardless.
  const handleAuthSuccess = useCallback(() => {
    hasPendingPostAuthSettleRef.current = true;
    setTimeout(() => onOpen(), REOPEN_AFTER_ACCOUNT_CREATION_DELAY_MS);
  }, [onOpen]);

  const wishlistAuthDrawer = useWishlistAuthDrawer({
    onAuthSuccess: handleAuthSuccess,
    intentId: CART_WISHLIST_INTENT_ID,
  });

  useEffect(() => {
    if (!isRegistered) {
      setIsGuestState(true);
      return;
    }
    // Steady-state (a shopper already registered when this container mounts) never sets the ref,
    // so `!hasPendingPostAuthSettleRef.current` is true immediately — no artificial wait for
    // someone with nothing to wait for.
    if (!hasPendingPostAuthSettleRef.current || queryClient.isMutating() === 0) {
      hasPendingPostAuthSettleRef.current = false;
      setIsGuestState(false);
    }
  }, [isRegistered, isMutatingSignal, queryClient]);

  /**
   * Opens the one shared wishlist auth drawer from any row's guest click. ZimmCartItemActions'
   * onGuestWishlistClick is `() => void` — no event to forward, because every row shares this one
   * drawer instance (ZimmCartItemActions' own docblock explicitly rejects one useWishlistAuthDrawer
   * per row). useWishlistAuthDrawer's handleTriggerClick needs a SyntheticEvent purely to capture
   * `e.currentTarget` as the AC10 focus-return target.
   *
   * document.activeElement is deliberately NOT used as a substitute here, even though it could
   * plausibly hold the real clicked row's own link at this exact point in the call stack:
   * useWishlistAuthDrawer.ts's own handleTriggerClick comment already documents exactly why it
   * chose `e.currentTarget` over `document.activeElement` for this identical purpose — "unlike
   * document.activeElement which may still be body on click." Building this on a mechanism that
   * file's own author already rejected for the same job would trade one honest degradation for a
   * silently unreliable one.
   *
   * 1:1 Figma-alignment audit fix, 2026-09-22 (Marcel's own direct report + decision): this used
   * to open the auth drawer without closing the cart first, so the two stacked — unmanaged
   * DOM/paint order, not a deliberate layering, since both use the same `zIndex: 'modal'`. Now
   * closes the cart drawer first (`onClose()`), so the auth drawer opens alone instead. This
   * supersedes this comment's own earlier note (removed here) about focus landing on the
   * still-open cart drawer's own sentinel on close — the cart isn't still open any more, so that
   * particular degradation no longer applies. See `handleAuthSuccess` above for the other half:
   * the cart reopens once the auth flow actually succeeds.
   */
  const openGuestWishlistDrawer = useCallback(() => {
    onClose();
    wishlistAuthDrawer.handleTriggerClick({ currentTarget: document.body } as unknown as SyntheticEvent<HTMLElement>);
  }, [onClose, wishlistAuthDrawer.handleTriggerClick]);

  /* -------------------------------------------------------------------------------------------
   * Pass criterion 3 — real remove/wishlist-move mutations, not stubs.
   * ---------------------------------------------------------------------------------------- */
  const removeItemFromBasketMutation = useShopperBasketsMutation('removeItemFromBasket');
  const updateItemInBasketMutation = useShopperBasketsMutation('updateItemInBasket');
  const customerId = useCustomerId();
  const { data: wishlist } = useWishList();
  const createCustomerProductListItem = useShopperCustomersMutation('createCustomerProductListItem');

  const removeItem = async (itemId?: string): Promise<void> => {
    if (!basket?.basketId || !itemId) return;
    await removeItemFromBasketMutation.mutateAsync({ parameters: { basketId: basket.basketId, itemId } });
    // 1:1 Figma-alignment audit fix, 2026-09-22 — see UseCurrentBasketReturn's own doc above.
    // Fire-and-forget: the header's bag count catching up a beat after this resolves is fine, the
    // removed line's own card is already gone from this drawer regardless.
    void refetchBasket();
  };

  // 1:1 Figma-alignment audit fix, 2026-09-22 — see this file's own module docblock. Mirrors
  // ProductItem's onItemQuantityChange contract exactly: resolve true only on a real, persisted
  // change, so the stepper's own "commit locally only if the mutation succeeded" logic
  // (handleStepperQuantityChange) can't ever show a quantity the basket didn't actually accept.
  const updateItemQuantity = async (itemId: string | undefined, quantity: number): Promise<boolean> => {
    if (!basket?.basketId || !itemId) return false;
    try {
      await updateItemInBasketMutation.mutateAsync({
        parameters: { basketId: basket.basketId, itemId },
        body: { quantity },
      });
      // Fire-and-forget, same reasoning as removeItem above — the stepper's own local state
      // already reflects the new quantity immediately; this only needs to reach the header.
      void refetchBasket();
      return true;
    } catch {
      return false;
    }
  };

  const moveToWishlist = async (productId: string): Promise<WishlistMoveResult> => {
    // Same lookup base product-detail/index.tsx's own handleAddToWishlist uses against
    // wishlist?.customerProductListItems.
    const isAlreadyInWishlist = wishlist?.customerProductListItems?.some(
      (item: { productId?: string }) => item.productId === productId,
    );
    if (isAlreadyInWishlist) {
      return { status: 'already-in-wishlist' };
    }
    if (!wishlist?.id) {
      // useWishList() auto-provisions a wish_list for a first-time registered customer and only
      // resolves it asynchronously (see that hook's own onSuccess) — surfaced as an error rather
      // than silently doing nothing, matching useCartMergeAndCap.ts's own "nothing valid to
      // address a write at" precedent.
      return { status: 'error', error: new Error('cartDrawerContainer: no wishlist available yet.') };
    }
    try {
      await createCustomerProductListItem.mutateAsync({
        parameters: {
          listId: wishlist.id,
          // SDK param widening — useCustomerId returns string | null; onMoveToWishlist is only
          // ever invoked for a registered shopper (ZimmCartItemActions only calls this prop
          // directly when isGuest is false, and the resumed path only fires once isGuest has
          // become false — see usePendingWishlistItem.ts), matching product-detail/index.tsx's
          // own identical cast for the same real precondition.
          customerId: customerId as string,
        },
        body: {
          // NOTE: API does not respect quantity, it always adds 1 — see WISHLIST_ADD_QUANTITY's
          // own comment above.
          quantity: WISHLIST_ADD_QUANTITY,
          productId,
          public: false,
          priority: 1,
          type: 'product',
        },
      });
      return { status: 'success' };
    } catch (error) {
      return { status: 'error', error };
    }
  };

  return (
    <>
      <ZimmCartDrawer
        isOpen={isOpen}
        onClose={onClose}
        itemCount={itemCount}
        finalFocusRef={finalFocusRef}
        // SFCC-317 — wired into its real, intended destination (see that component's own
        // docblock: "provisional placement" on the PDP tab, "until cart drawer ships"). Renders
        // nothing if Contentful has no published `iconAndText`/`benefits` entry — same
        // already-established behaviour as the PDP tab.
        //
        // 1:1 Figma-alignment audit fix, 2026-09-23 (Marcel's direct report): omitted entirely on
        // an empty cart, not just left to render whatever ZimmBenefits itself decides — the empty
        // state has no benefits strip in Figma at all, and `footer` isn't passed a real element
        // in this case so ZimmCartDrawer's own conditional wrapper (index.tsx) skips rendering it
        // too, rather than leaving an empty, still-margined box behind.
        footer={itemCount === 0 ? undefined : <ZimmBenefits />}
      >
        {itemCount === 0 ? (
          <ZimmCartEmptyState onContinueShoppingClick={onClose} />
        ) : (
          <>
            <CartItemsColumn
              productItems={productItems}
              productsById={productsById}
              isProductsLoading={isProductsLoading}
              isGuestState={isGuestState}
              alreadyInWishlistItemIds={alreadyInWishlistItemIds}
              onAlreadyInWishlist={markAlreadyInWishlist}
              onClose={onClose}
              updateItemQuantity={updateItemQuantity}
              removeItem={removeItem}
              moveToWishlist={moveToWishlist}
              openGuestWishlistDrawer={openGuestWishlistDrawer}
            />
            {/* Column 2 (26.875rem desktop track) — the real Figma column also holds a totals
                breakdown, promotion code, and recommended-for-you below this, all still out of
                scope (see this file's own docblock). At/above `xl` this renders as a plain grid
                sibling (the 140px column-gap already separates it from column 1 — no border or
                extra margin needed there). Below `xl`, `body` collapses to a single flex column
                (zimmCartDrawer.css.ts) with no gap of its own between its children — but Figma's
                own tablet frame (node 9323:65993, "Totals-summary") shows this section is NOT
                simply adjacent to the items: it sits 48px below them (Cart Summary's own gap),
                behind a black top border, with its own further 32px of padding before the
                button group starts. Confirmed against the real tablet frame directly, not
                guessed — reproduced here rather than on ZimmCartDrawer itself since it's specific
                to how these two particular children relate, not a generic drawer-body concern.
                1:1 Figma-alignment audit fix, 2026-09-22 (Marcel's direct report) — desktop-only
                `paddingBottom`: the real `Totals-summary` node (9323:95939) carries
                `pb-[var(--alias/space/800,32px)]` on itself, reserved below its content within
                its own column-height-stretched box — confirmed directly against the raw node
                data, not inferred (contrast the items column's own matching value above, which
                *is* inferred). Same var(--zimm-scale-2xl) token as the tablet/mobile
                `paddingTop` above — same 32px value, opposite edge, different breakpoint. */}
            <Box
              sx={{
                borderTop: '1px solid var(--zimm-color-text-default)',
                marginTop: 'var(--zimm-scale-1200)',
                paddingTop: 'var(--zimm-scale-2xl)',
                [`@media (min-width: ${breakpoints.xl})`]: {
                  borderTop: 'none',
                  marginTop: 0,
                  paddingTop: 0,
                  paddingBottom: 'var(--zimm-scale-2xl)',
                },
              }}
            >
              <ZimmCartButtonGroup />
            </Box>
          </>
        )}
      </ZimmCartDrawer>
      <CartWishlistAuthGate wishlistAuthDrawer={wishlistAuthDrawer} />
    </>
  );
};

